20	/**
21	 * Downloads an object
22	 */
23	export async function getR2Object(
24		complianceConfig: ComplianceConfig,
25		accountId: string,
26		bucketName: string,
27		objectName: string,
28		jurisdiction?: string
29	): Promise<ReadableStream | null> {
30		const headers: HeadersInit = {};
31		if (jurisdiction !== undefined) {
32			headers["cf-r2-jurisdiction"] = jurisdiction;
33		}
34		const response = await fetchR2Objects(
35			complianceConfig,
36			`/accounts/${accountId}/r2/buckets/${bucketName}/objects/${objectName}`,
37			{
38				method: "GET",
39				headers,
40			}
41		);
42	
43		return response === null ? null : response.body;
44	}
