import { confirm } from "../../dialogs";
import { logger } from "../../logger";

/**
 * Header sent on R2 write requests to ask the API to reject the operation
 * (with an HTTP 409 / code 10081) when the target bucket has data catalog
 * enabled. This lets the CLI warn the user before proceeding.
 */
export const DATA_CATALOG_CHECK_HEADER = "cf-r2-data-catalog-check";

/**
 * The API error code returned (alongside HTTP 409) when a write is blocked
 * because the bucket has data catalog enabled.
 */
const DATA_CATALOG_CONFLICT_CODE = 10081;

/**
 * Prompt shown when a per-operation write is blocked by the data catalog check.
 */
export const DATA_CATALOG_CONFLICT_PROMPT =
	"Data catalog is enabled for this bucket. Proceeding may leave the data catalog in an invalid state. Continue?";

/**
 * Upfront prompt shown before a bulk upload, which cannot cheaply perform a
 * per-object data catalog check.
 */
export const BULK_UPLOAD_DATA_CATALOG_PROMPT =
	"Bulk upload may overwrite existing objects. If this bucket has data catalog enabled, this operation could leave the catalog in an invalid state. Continue?";

/**
 * Returns whether the given error is the data catalog conflict error
 * (HTTP 409 / code 10081) surfaced by the R2 API.
 */
export function isDataCatalogConflict(error: unknown): boolean {
	return error instanceof APIError && error.code === DATA_CATALOG_CONFLICT_CODE;
}

/**
 * Runs a write operation guarded by the data catalog safety check.
 *
 * When `force` is `true`, the operation runs immediately without the data
 * catalog check header.
 *
 * When `force` is `false`, the operation first runs with the data catalog
 * check header enabled. If the API reports that the bucket has data catalog
 * enabled (HTTP 409 / code 10081), the user is prompted before retrying the
 * operation without the check header.
 *
 * @returns `true` if the operation was performed, `false` if the user declined
 *   the confirmation prompt (in which case a cancellation message is logged).
 */
export async function withDataCatalogCheck(
	force: boolean,
	operation: (dataCatalogCheck: boolean) => Promise<void>
): Promise<boolean> {
	if (force) {
		await operation(false);
		return true;
	}

	try {
		await operation(true);
		return true;
	} catch (error) {
		if (!isDataCatalogConflict(error)) {
			throw error;
		}

		const confirmed = await confirm(DATA_CATALOG_CONFLICT_PROMPT);
		if (!confirmed) {
			logger.log("Operation cancelled.");
			return false;
		}

		await operation(false);
		return true;
	}
}
